import numpy as np
DESCRIPTION=("One-hot token+position embeddings. Layer 0 scores key j at query p by e[p].A0.e[j], softmaxes and adds the values e[j].P0, so each position holds a soft summary of the map. Layer 1 reads position 5, scores keys by r0[5].A1.r0[j], mixes them into v1; output r0[5].W_U+v1.(P1.W_U)=logits.")
WE=np.array([[-60969,-10573,-161046,37638,111281,-18180,-15772,1979],[-6873,-26649,-24658,27472,43709,19934,-23682,24848],[95515,-109118,-31497,-82743,40391,41886,18717,95229],[-17976,217998,46378,-35221,44920,114406,-8328,21627],[-106197,9222,134270,28462,44127,-19730,40206,-9179],[-201231,-3982,-72046,-130294,33138,1500,90650,29041]])*1e-5
WP=np.array([[-45759,115201,-3388,73710,32432,-122231,-61920,124384],[54130,-74469,-107019,-13337,-121774,50850,111443,-26388],[-66460,-21309,5556,21472,-54442,86766,-25042,357784],[-52671,-84457,32375,-8022,35778,73951,-166473,-47341],[-36081,-21229,-50915,-437719,27190,-55130,-39586,-75803],[1011,71595,66068,45896,262048,31745,116478,-5759]])*1e-5
