P0=np.array([[14504,56759,-7386,-4080,31395,-60602,34934,20776],[-7787,68644,-24230,17144,21278,-3229,-8774,6205],[-11200,6029,-33740,16889,-5632,1123,18267,237],[937,5660,42059,533,36023,-101652,16856,17493],[-76764,-13986,-355,32712,36063,-365309,149171,18403],[-34809,-147316,45052,-31095,-49827,-48320,59249,4080],[-48889,34038,33610,-11132,14004,-186709,99147,19864],[-9562,31550,42968,3115,18466,-61116,6505,793]])*1e-5
A1=np.array([[14413,13989,-6205,-22954,40435,32383,40673,34727],[-8941,-28122,-14191,4908,-33332,-26499,-37150,9612],[10531,103,10962,11433,23746,14542,24349,-8219],[19861,-60105,20712,96266,-19651,-14449,-49565,2437],[4208,9835,-24289,16580,-111504,-59908,-68477,-12843],[17720,-16307,34449,64102,63921,33818,43155,-10224],[-13093,-18524,69388,88014,47989,28594,10733,54860],[30768,-153391,95744,296014,89763,18879,-1096,-40956]])*1e-5
MW=np.array([[368183,73120,-135659,-77620,-32249,7559],[-137694,112076,18132,-30711,-56083,-81094],[-1581783,1259900,163193,-151267,-194855,-178934],[-1277006,1647538,-1860,-328625,-338387,-284274],[-409565,251487,52602,-65931,-134810,-208246],[-215162,33937,47359,15464,-3760,-22010],[-380084,200183,54892,-8630,-26264,-35143],[161586,-86887,-28193,-6071,-7154,-16327]])*1e-5
WU=np.array([[-229716,2529,67406,117968,184301,285767],[9450,47781,-21127,-12144,-4438,10636],[54778,-80724,-6639,12521,9451,1667],[192877,80881,-94006,-87087,-70177,-66078],[141856,-284870,-14230,8421,-27958,-100435],[137706,-58089,-20261,-34267,-54323,-81793],[196811,-83703,-15918,38854,73775,118503],[492138,327054,-127248,-257296,-330113,-423801]])*1e-5

def model(x,iv):
    u=np.arange(6)
    t=[iv("t%d"%p,(x[:,p][:,None]==u).astype(float)) for p in range(6)]
    E=np.stack([s@WE for s in t],1)+WP
    z=np.einsum('bpd,bjd->bpj',E@A0,E);z=np.exp(z-z.max(2,keepdims=True));z/=z.sum(2,keepdims=True)
    z=np.stack([iv("a%d"%p,z[:,p]) for p in range(6)],1)
    r=E+np.einsum('bpj,bjd->bpd',z,E@P0)
    r=np.stack([iv("r%d"%p,r[:,p]) for p in range(6)],1)
    z=np.einsum('bd,bjd->bj',r[:,5]@A1,r);z=np.exp(z-z.max(1,keepdims=True));z/=z.sum(1,keepdims=True)
    z=iv("a1q",z)
    return iv("logits",r[:,5]@WU+iv("v1",np.einsum('bj,bjd->bd',z,r))@MW)
A={"t%d"%p:["embed"] for p in range(6)}
A.update({"a%d"%p:["attn0.pattern"] for p in range(6)})
A.update({"r%d"%p:["resid0.mid"] for p in range(6)})
A.update({"a1q":["attn1.pattern"],"v1":["attn1.out"],"logits":["resid1.mid"]});ALIGN=A
